-- Your safe string parser
local function ParseCSV(str, isNumber)
    local t = {}
    local inQuote, current = false, ""
    for i = 1, #str do
        local char = str:sub(i,i)
        if char == '"' then inQuote = not inQuote
        elseif char == ',' and not inQuote then
            local val = current:match("^%s*(.-)%s*$")
            if val ~= "" then table.insert(t, isNumber and tonumber(val) or val) end
            current = ""
        else current = current .. char end
    end
    local val = current:match("^%s*(.-)%s*$")
    if val and val ~= "" then table.insert(t, isNumber and tonumber(val) or val) end
    return t
end

