-- Build the final crafting roster and feed it to the main addon
for i = 1, #Names do
    if Names[i] and Reqs[i] then
        local rawProf, skillLevelStr = string.match(Reqs[i], "([A-Za-z%s%-]+)%s*(%d*)")
        rawProf = rawProf and rawProf:match("^%s*(.-)%s*$") or "Unknown"
        
        local baseProf = rawProf
        local reqSpec = nil
        
        for _, spec in ipairs(specializations) do
            if rawProf:find(spec) then
                reqSpec = spec
                baseProf = rawProf:gsub(spec, ""):match("^%s*(.-)%s*$")
                break
            end
        end
        
        local minSkill = tonumber(skillLevelStr) or 1
        local maxSkill = minSkill + 50
        
        local itemData = {
            name = Names[i],
            minSkill = minSkill,
            maxSkill = maxSkill,
            reqProf = baseProf,
            reqSpec = reqSpec
        }

        -- Divert items found on the Blacklist to the Legendary DB
        if LegendaryBlacklist[Names[i]] then
            table.insert(DP.LegendaryCraftingDB, itemData)
        else
            table.insert(DP.CraftingDB, itemData)
        end
    end
end